      "tipo": "GC",
      "causa_raiz": "Concatenação contínua de strings com o operador '+' dentro de laços de repetição (s += i.ToString()) e instanciação repetida de arrays (new object[10000]) a cada frame no método Update. Strings em C# são imutáveis, de modo que cada concatenação aloca um novo objeto na memória Heap gerenciada, acumulando mais de 10 MB de lixo por frame e forçando pausas de coleta de lixo (GC.Collect) de mais de 21 ms.",
      "codigo_refatorado": "using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;
        [Range(1, 50)]
        public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)]
        public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private StringBuilder _cachedStringBuilder;
        private object[][] _reusableArrayPool;
        private MaterialPropertyBlock _propertyBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");

        private void Awake()
        {
            _cachedStringBuilder = new StringBuilder(gcConcatIterations * 8);
            _propertyBlock = new MaterialPropertyBlock();
            if (gcArrayAllocs > 0)
            {
                _reusableArrayPool = new object[gcArrayAllocs][];
                for (int i = 0; i < gcArrayAllocs; i++)
                {
                    _reusableArrayPool[i] = new object[10000];
                }
            }
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject("Empty_" + i);
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _cachedStringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _cachedStringBuilder.Append(i);
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    Color randomColor = new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value);

                    renderer.GetPropertyBlock(_propertyBlock);
                    _propertyBlock.SetColor(ColorPropertyId, randomColor);
                    renderer.SetPropertyBlock(_propertyBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Imagine a memória Heap como uma mesa de trabalho. Toda vez que você usa texto com o operador '+' repetidas vezes, você cria um papel novo e joga o anterior no chão. Quando a mesa enche, o 'Coletor de Lixo' (Garbage Collector) é obrigado a parar o jogo para limpar tudo, provocando engasgos visíveis (stutter). Utilizar um StringBuilder reaproveita o mesmo espaço sem criar sujeira na memória. Além disso, usar MaterialPropertyBlock permite colorir objetos de forma única sem duplicar materiais no motor gráfico."
    },
    {
      "tipo": "CPU",
      "causa_raiz": "Chamada repetitiva a 'GameObject.FindObjectsOfType<GameObject>()' dentro de um loop no Update. Esta API varre recursivamente toda a árvore de objetos da cena no lado nativo em C++ e aloca um array com todos eles para o C#, resultando em consumo de mais de 130 ms por frame.",
      "codigo_refatorado": "// Para otimizar a busca por objetos, evite varreduras de cena em runtime.
// Utilize um padrão de registro (Registry Pattern) ou listas gerenciadas:

using System.Collections.Generic;
using UnityEngine;

public class SceneObjectRegistry : MonoBehaviour
{
    public static readonly List<GameObject> ActiveObjects = new List<GameObject>(1024);

    private void OnEnable()
    {
        ActiveObjects.Add(gameObject);
    }

    private void OnDisable()
    {
        ActiveObjects.Remove(gameObject);
    }
}",
      "explicacao_didatica": "Procurar objetos em cena com FindObjectsOfType durante o Update é como ler uma lista telefônica inteira do início ao fim 60 vezes por segundo para achar seus contatos. Em vez de procurar tudo a cada instante, cada objeto deve simplesmente avisar quando 'entrou' ou 'saiu' do jogo, mantendo uma lista sempre pronta e acessível sem esforço computacional."
    }
  ],
  "dicas_level_design": null
}

